"use client";
import { useLayoutEffect, useRef, useState, type CSSProperties } from "react";
import "./continuous-tabs.css";
export interface ContinuousTab {
  id: string;
  label: React.ReactNode;
}
/** A controlled selection group. Labels never move; one retained marker follows selection. */
export function ContinuousTabs({
  items,
  value,
  onValueChange,
  label = "View",
  color,
  duration,
  className = "",
  style,
}: {
  className?: string;
  style?: CSSProperties;
  items: ContinuousTab[];
  value: string;
  onValueChange: (id: string) => void;
  label?: string;
  color?: string;
  duration?: number;
}) {
  const root = useRef<HTMLDivElement>(null),
    [pose, setPose] = useState({ x: 0, width: 0 });
  useLayoutEffect(() => {
    const measure = () => {
      const button =
        root.current?.querySelector<HTMLElement>(`[data-active="true"]`);
      if (button) setPose({ x: button.offsetLeft, width: button.offsetWidth });
    };
    measure();
    const observer = new ResizeObserver(measure);
    if (root.current) observer.observe(root.current);
    return () => observer.disconnect();
  }, [value, items]);
  return (
    <div
      className={`roc-tabs ${className}`}
      ref={root}
      style={
        {
          "--roc-marker": color,
          "--roc-duration": duration ? `${duration}ms` : undefined,
          ...style,
        } as CSSProperties
      }
      role="group"
      aria-label={label}
    >
      <span
        aria-hidden="true"
        className="roc-tab-marker"
        style={{ transform: `translateX(${pose.x}px)`, width: pose.width }}
      />
      {items.map((item) => (
        <button
          type="button"
          key={item.id}
          data-active={value === item.id}
          aria-pressed={value === item.id}
          onClick={() => onValueChange(item.id)}
        >
          {item.label}
        </button>
      ))}
    </div>
  );
}

@import "./surface.css";
.roc-tabs * {
  box-sizing: border-box;
}
.roc-tabs button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
.roc-tabs {
  position: relative;
  display: inline-flex;
  border: 1px solid var(--roc-line, #d8dcd4);
  padding: 4px;
  border-radius: 9px;
  background: #f0f1eb;
  max-width: 100%;
}
.roc-tabs button {
  position: relative;
  z-index: 1;
  background: none;
  border: 0;
  padding: 11px 18px;
  font-size: 12px;
  border-radius: 5px;
  white-space: nowrap;
  transition: color 250ms cubic-bezier(0.22, 1, 0.36, 1);
}
.roc-tabs button[data-active="true"] {
  color: #2c4227;
}
.roc-tab-marker {
  position: absolute;
  left: 0;
  top: 4px;
  bottom: 4px;
  border-radius: 5px;
  background: #fff;
  box-shadow: 0 1px 4px #20282012;
  transition:
    transform 0.36s cubic-bezier(0.22, 0.8, 0.25, 1),
    width 0.36s cubic-bezier(0.22, 0.8, 0.25, 1);
}
@media (max-width: 480px) {
  .roc-tabs button {
    padding: 10px 12px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-tabs * {
    transition: none !important;
    animation: none !important;
  }
}
.roc-tab-marker {
  transition:
    transform var(--roc-duration, 360ms) cubic-bezier(0.22, 0.8, 0.25, 1),
    width var(--roc-duration, 360ms) cubic-bezier(0.22, 0.8, 0.25, 1);
  background: var(--roc-marker, #fff);
}
@media (prefers-reduced-motion: reduce) {
  .roc-tab-marker {
    transition: none !important;
  }
}

@import "./animation.css";
@import "./corners.css";
@import "./responsive.css";
/* Shared surface primitives only. Tokens inherit from the host. No page reset. */
:where(
  .roc-expand,
  .roc-folder,
  .roc-sources,
  .roc-lanes,
  .roc-tabs,
  .roc-card-preview,
  .roc-image-viewport,
  .roc-voice,
  .roc-selection-toolbar,
  .roc-page-book,
  .roc-source-tray
) {
  color: var(--roc-ink, #30332e);
  font-family: inherit;
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  * {
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
.roc-image-viewport:focus-visible,
.roc-page-book:focus-visible,
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--roc-focus, #737373) !important;
}
@media (forced-colors: active) {
  .roc-image-viewport:focus-visible,
  .roc-page-book:focus-visible,
  :where(
      .roc-expand,
      .roc-folder,
      .roc-sources,
      .roc-lanes,
      .roc-tabs,
      .roc-card-preview,
      .roc-image-viewport,
      .roc-voice,
      .roc-selection-toolbar,
      .roc-page-book,
      .roc-source-tray
    )
    button:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
.roc-eyebrow {
  font:
    10px/1.4 ui-monospace,
    monospace;
  letter-spacing: 0.12em;
  color: var(--roc-muted, #757b72);
}
.roc-text-button {
  border: 0;
  background: none;
  padding: 9px 0;
  font-size: 12px;
  text-align: left;
  display: inline-flex;
  gap: 20px;
  align-items: center;
}

/* ROC owns motion; Base UI owns interaction and portal presence. */
/* These parts use spring positions, so a CSS transition would lag the pointer. */
.roc-ui[data-slot="slider-thumb"],
.roc-ui[data-slot="slider-range"] {
  transition-property: background-color, border-color, box-shadow;
}
/* Static content stays still; interactive surfaces respond to state changes. */
:where(.roc-ui, .roc-shadcn):is(
  [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
  [data-slot="table-row"], [data-slot="sidebar-menu-button"]
) {
  transition: background-color 150ms ease-out, border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  :where(.roc-ui, .roc-shadcn):is(
    [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
    [data-slot="table-row"], [data-slot="sidebar-menu-button"]
  ) { transition: none; }
}

/* Smooth squircle corners, following the visual treatment at https://corne.rs/.
   Native corner shaping keeps borders, shadows and overflowing content intact.
   Browsers without support retain the existing border-radius fallback. */
:where(
  [class^="roc-"],
  [class*=" roc-"],
  [class^="roc-"] *,
  [class*=" roc-"] *
) {
  /* ROC limits by role, informed by Apple's compact-control and surface guidance.
     These are ROC values, not platform-prescribed dimensions. Zero stays square. */
  --roc-radius-compact: min(var(--roc-radius, 9px), 8px);
  --roc-radius-control: min(var(--roc-radius, 9px), 10px);
  --roc-radius-popup: min(var(--roc-radius, 9px), 12px);
  --roc-radius-surface: min(var(--roc-radius, 12px), 20px);
}
@supports (corner-shape: squircle) {
  :where(
    [class^="roc-"],
    [class*=" roc-"],
    [class^="roc-"] *,
    [class*=" roc-"] *
  ) {
    corner-shape: var(--roc-corner-shape, squircle);
  }
}

/* Shared viewport constraints for portalled controls, including standalone consumers. */
:is(.roc-ui, .roc-shadcn)[data-slot]:is(
  [data-slot="popover-content"],
  [data-slot="hover-card-content"],
  [data-slot="tooltip-content"],
  [data-slot="select-content"],
  [data-slot="combobox-content"],
  [data-slot="dropdown-menu-content"],
  [data-slot="dropdown-menu-sub-content"],
  [data-slot="context-menu-content"],
  [data-slot="context-menu-sub-content"],
  [data-slot="menubar-content"],
  [data-slot="menubar-sub-content"]
) {
  max-inline-size: min(var(--available-width, calc(100vw - 24px)), calc(100vw - 24px));
  max-block-size: min(var(--available-height, calc(100dvh - 24px)), calc(100dvh - 24px));
  overflow: auto;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
}
@media (max-width: 640px), (pointer: coarse) {
  .roc-ui.roc-ui-button[data-slot],
  .roc-ui[data-slot="native-select"],
  .roc-shadcn[data-slot="select-trigger"] {
    min-height: 44px;
  }
  .roc-ui.roc-ui-button[data-size^="icon"] {
    width: 44px;
    height: 44px;
  }
  .roc-ui[data-slot="input"],
  .roc-ui[data-slot="textarea"],
  .roc-shadcn[data-slot="input-group-control"] {
    font-size: 16px;
  }
  .roc-ui[data-slot="input"],
  .roc-shadcn[data-slot="input-group"],
  .roc-ui[data-slot="slider"] {
    min-height: 44px;
  }
  .roc-shadcn[data-slot="input-group"] [data-slot="input-group-control"] {
    min-height: 42px;
  }
  .roc-sidebar-link,
  .roc-ui[data-slot="tabs-trigger"],
  .roc-ui[data-slot="toggle"],
  .roc-shadcn[data-slot="select-item"],
  .roc-shadcn[data-slot="combobox-item"] {
    min-height: 44px;
  }
  .roc-ui[data-slot="dropdown-menu-item"],
  .roc-ui[data-slot="dropdown-menu-checkbox-item"],
  .roc-ui[data-slot="dropdown-menu-radio-item"],
  .roc-shadcn[data-slot="context-menu-item"],
  .roc-shadcn[data-slot="menubar-item"] {
    min-height: 44px;
  }
}
